// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 firstAmount, uint256 secondAmount) public {
        firstAmount = bound(firstAmount, 1, 1 ether);
        secondAmount = bound(secondAmount, 1, 1 ether);

        address depositor1 = address(0xABCD);
        address depositor2 = address(0xBEEF);

        vm.deal(depositor1, firstAmount);
        vm.deal(depositor2, secondAmount);

        vm.prank(depositor1);
        (bool ok1, ) = address(c).call{value: firstAmount}("");
        require(ok1, "first deposit failed");

        uint256 afterFirst = c.depositsCount();

        vm.prank(depositor2);
        (bool ok2, ) = address(c).call{value: secondAmount}("");
        require(ok2, "second deposit failed");

        assertTrue(c.depositsCount() >= 1);

    }
}
